//! Independent immutable old registration, actual old Walker and semantic model.
use crate::lint::Registry;
#[path="../fixtures/original_policies/rel_write_original_raw_events.rs"]mod original_events;
#[path="../fixtures/original_policies/rel_write_undeclared_workspace.rs"]mod original;
#[path="../fixtures/native-rel-write-workspace/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod scratch;
#[test]fn original_rel_write_undeclared_whole_reports_cover_statement_roots_shadow_return_fallback_maps_and_macros(){use sha1::Digest as _;assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/rel_write_undeclared_workspace.rs"))),"e7325a483f065b866a5b61c521fb669393d5e50a");assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/rel_write_original_raw_events.rs"))),"4f98c26585f6abc5ad80bed272baf5f19bfd4bfd");for case in fixture::CASES{let root=scratch::dir(&format!("old-rel-write-{case}"));for(relative,bytes)in fixture::files(case){let target=root.join(relative);std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::write(target,bytes).unwrap();}let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,crate::run::Options{root:root.clone(),lints:vec!["rel_write_undeclared".into()],no_cache:true,raw:true,..Default::default()}).unwrap();let sem=crate::sem::sem_for(&old.tree).unwrap();assert!(sem.errors.is_empty(),"actual old parsing failed: {:?}",sem.errors);if matches!(*case,"noncode"|"noncode_decl"){let mut map_body=false;for ty in sem.objtree.iter_types(){for(_,proc_type)in ty.get().procs.iter(){for body in proc_type.value.iter(){if body.code.is_some()&&sem.file_of(body.location)==Some("maps/relation.dm"){map_body=true}}}}assert!(map_body,"the actual Original loader must compile the map procedure before the policy domain is tested");}let metadata=old.reg.lints[0].meta();let scope=old.scopes.for_lint(metadata.name,metadata.group);let cx=crate::lint::Cx{tree:&old.tree,meta:metadata,scope:&scope};let index=crate::lints::stored_refs::relation_index(&cx);assert!(index.get("declared").is_some_and(|types|types.iter().any(|ty|ty=="/datum/holder")),"actual old declarations ignore this lint's exemptions");if *case=="noncode_decl"{assert!(!index.contains_key("map_only"),"map-only declarations are outside actual old raw CODE index");}for file in cx.all_files(){let frozen=original_events::file_events(&file.rel,file.raw(),file.code());let current=crate::raw_ownership_policy::file_events(&file.rel,file.raw(),file.code());assert_eq!(serde_json::to_value(frozen).unwrap(),serde_json::to_value(current).unwrap(),"same complete old structural events for {}",file.rel);}let outcome=old.run_one(old.reg.lints[0].as_ref());assert!(outcome.internal_error.is_none());if *case=="exempt"{assert!(outcome.run.sites.is_empty());}else{assert!(!outcome.run.sites.is_empty(),"genuine positive {case}");}if *case=="noncode"{assert!(outcome.run.sites.iter().any(|s|s.rel=="maps/relation.dm"),"old body domain includes map procs after selected CODE declarations");}assert!(outcome.run.notes.is_empty()&&outcome.allow_used.is_empty());println!("ORIGINAL_REL_WRITE_FULL={}",serde_json::json!({"case":case,"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text}));}}
